<script>
  let {
    class: klass = '',
    status = $bindable('info'),
    statusText = '',
    children,
    ...rest
  } = $props()

  const statusClasses = {
    info: 'status-info',
    success: 'status-success',
    error: 'status-error',
  }

  function getStatusString(status) {
    if (typeof status === 'string') return status
    if (status >= 200 && status < 300) return 'success'
    if (status >= 300 && status < 400) return 'redirect'
    if (status >= 400) return 'error'
    return 'info'
  }

  function getStatusClass(status) {
    return statusClasses[getStatusString(status)]
  }

  let statusClass = $derived(getStatusClass(status))
  let role = $derived(getStatusString(status) === 'error' ? 'alert' : 'status')
</script>

<output
  {...rest}
  class="status {statusClass} {klass}"
  class:sr-only={!statusText && !children}
  {role}
>
  {#if statusText}
    {statusText}
  {:else}
    {@render children?.()}
  {/if}
</output>
